<?php
declare(strict_types=1);
$out = __DIR__;
$purple='#7558D1'; $lavender='#E1DAFB'; $pale='#F8F6FF'; $ink='#241B35'; $muted='#746B83'; $line='#8B7BB2'; $white='#FFFFFF'; $orange='#F29A38';
function t($x,$y,$s,$size=22,$fill='#241B35',$weight=400,$anchor='start'): string { return '<text x="'.$x.'" y="'.$y.'" font-family="Inter,Segoe UI,Arial,sans-serif" font-size="'.$size.'" font-weight="'.$weight.'" fill="'.$fill.'" text-anchor="'.$anchor.'">'.htmlspecialchars((string)$s,ENT_QUOTES|ENT_XML1,'UTF-8').'</text>'; }
function svgStart($w,$h,$title,$desc): array { return ['<svg xmlns="http://www.w3.org/2000/svg" width="'.$w.'" height="'.$h.'" viewBox="0 0 '.$w.' '.$h.'" role="img" aria-labelledby="title desc"><title id="title">'.htmlspecialchars($title,ENT_XML1,'UTF-8').'</title><desc id="desc">'.htmlspecialchars($desc,ENT_XML1,'UTF-8').'</desc><defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#FBFAFF"/><stop offset="1" stop-color="#F1ECFF"/></linearGradient><filter id="shadow" x="-10%" y="-10%" width="120%" height="130%"><feDropShadow dx="0" dy="5" stdDeviation="8" flood-color="#4B3477" flood-opacity=".12"/></filter><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="#8B7BB2"/></marker><marker id="arrowDashed" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="#F29A38"/></marker></defs><rect width="100%" height="100%" fill="url(#bg)"/>']; }
function heading(&$p,$title,$subtitle,$y=75): void { $p[]=t(80,$y,$title,46,'#7558D1',750); $p[]=t(82,$y+42,$subtitle,22,'#746B83',450); }
function entity(&$p,$x,$y,$w,$name,$fields,$note=null,$legacy=false): void {
  $lh=34; $h=66+count($fields)*$lh+($note?42:0); $border=$legacy?'#F29A38':'#7558D1';
  $p[]='<g filter="url(#shadow)"><rect x="'.$x.'" y="'.$y.'" width="'.$w.'" height="'.$h.'" rx="16" fill="#FFFFFF" stroke="'.$border.'" stroke-width="3"/><path d="M'.($x+16).' '.$y.' H'.($x+$w-16).' Q'.($x+$w).' '.$y.' '.($x+$w).' '.($y+16).' V'.($y+61).' H'.$x.' V'.($y+16).' Q'.$x.' '.$y.' '.($x+16).' '.$y.'" fill="'.$border.'"/></g>';
  $p[]=t($x+22,$y+42,$name,26,'#FFFFFF',750); $fy=$y+91;
  foreach($fields as [$field,$tag]) { $p[]=t($x+22,$fy,$field,20,'#241B35',$tag?600:450); if($tag){$c=$tag==='FK*'?'#F29A38':'#7558D1';$tw=$tag==='FK*'?62:54;$p[]='<rect x="'.($x+$w-$tw-18).'" y="'.($fy-23).'" width="'.$tw.'" height="26" rx="8" fill="'.$c.'" opacity=".13"/>';$p[]=t($x+$w-18-$tw/2,$fy-4,$tag,15,$c,750,'middle');} $fy+=$lh; }
  if($note){$p[]='<path d="M'.($x+18).' '.($fy-7).' H'.($x+$w-18).'" stroke="#E8E2F3" stroke-width="2"/>';$p[]=t($x+22,$fy+24,$note,16,'#746B83',500);}
}
function edge(&$p,$d,$label,$lx,$ly,$dashed=false): void { $c=$dashed?'#F29A38':'#8B7BB2';$marker=$dashed?'arrowDashed':'arrow';$dash=$dashed?' stroke-dasharray="11 9"':'';$p[]='<path d="'.$d.'" fill="none" stroke="'.$c.'" stroke-width="3"'.$dash.' marker-end="url(#'.$marker.')"/><rect x="'.($lx-120).'" y="'.($ly-20).'" width="240" height="30" rx="8" fill="#FBFAFF" opacity=".96"/>'.t($lx,$ly,$label,16,$c,650,'middle'); }
function saveSvg($out,$name,$p): void { file_put_contents($out.'/'.$name,implode("\n",[...$p,'</svg>'])); }
$p=svgStart(3600,2500,'Dailee — Entity Relationship Diagram','ERD fitur Dailee berdasarkan tabel yang ada di database bereal_db, mencakup akun, momen, pertemanan, interaksi, pesan, dan agenda.');
heading($p,'DAILEE · ENTITY RELATIONSHIP DIAGRAM','Skema database bereal_db • 11 tabel fitur • garis putus-putus menandai relasi yang dipakai aplikasi tetapi belum tentu dipaksa oleh foreign key MySQL');
edge($p,'M 610 1010 H 750 V 360 H 900','1 : N  ·  agenda milik akun',780,690); edge($p,'M 610 1010 H 790 V 880 H 900','1 : N  ·  pengirim / penerima permintaan',790,940); edge($p,'M 610 1010 H 810 V 1320 H 900','1 : N  ·  follower / following',805,1255); edge($p,'M 610 1010 H 830 V 1640 H 900','1 : N  ·  sender / receiver',835,1580); edge($p,'M 610 1290 H 680 V 1760 H 1600 V 950 H 1760','1 : N  ·  pemilik momen',1190,1730); edge($p,'M 610 1010 H 750 V 1930 H 900','1 : N  ·  jadwal akademik lama',790,1885,true); edge($p,'M 1440 360 H 1580 V 800 H 1760','0..1 : N  ·  momen dapat ditautkan ke agenda',1620,570,true); edge($p,'M 2300 800 H 2450 V 430 H 2600','1 : N  ·  label / hashtag',2480,595); edge($p,'M 2300 820 H 2600','1 : N  ·  komentar',2470,805,true); edge($p,'M 2300 900 H 2490 V 1110 H 2600','1 : N  ·  reaksi (like / emoji)',2480,1010,true); edge($p,'M 2300 950 H 2520 V 1530 H 2600','1 : N  ·  riwayat share',2510,1315,true);
entity($p,80,710,530,'users',array_map(fn($x)=>[$x,in_array($x,['id'],true)?'PK':''],['PK  id','name','email  ·  unique','username  ·  unique','nama_lengkap','password  ·  hash','role','avatar','created_at','updated_at','location','occupation','education','zodiac_or_interest','bio']),'Profil, autentikasi, dan data akun');
entity($p,900,100,540,'schedules',array_map(fn($x)=>[$x,str_starts_with($x,'user_id')?'FK*':''],['PK  id','user_id','title','category','description','date','start_time','end_time','location','status','created_at','alert_time','sync_calendar']),'Agenda, tugas, pengingat, kalender');
entity($p,900,710,540,'friendships',array_map(fn($x)=>[$x,$x==='PK  id'?'PK':(in_array($x,['user_id','friend_id'],true)?'FK*':'')],['PK  id','user_id','friend_id','status','created_at']),'Status: pending · accepted · rejected');
entity($p,900,1120,540,'follows',array_map(fn($x)=>[$x,in_array($x,['PK  id','follower_id','following_id'],true)?(str_contains($x,'PK')?'PK':'FK'):''],['PK  id','follower_id','following_id','created_at']),'Unik per pasangan follower → following');
entity($p,900,1460,540,'chats',array_map(fn($x)=>[$x,in_array($x,['PK  id','sender_id','receiver_id'],true)?(str_contains($x,'PK')?'PK':'FK*'):''],['PK  id','sender_id','receiver_id','message','created_at']),'Pesan langsung; akses dibatasi ke teman mutual');
entity($p,900,1800,540,'academic_schedule',array_map(fn($x)=>[$x,in_array($x,['PK  id','user_id'],true)?(str_contains($x,'PK')?'PK':'FK'):''],['PK  id','user_id','title','category','due_date','is_done','created_at']),'Tabel jadwal akademik lama / legacy',true);
entity($p,1760,680,540,'moments',array_map(fn($x)=>[$x,in_array($x,['PK  id','user_id'],true)?(str_contains($x,'PK')?'PK':'FK'):(str_starts_with($x,'schedule_id')?'FK*':'')],['PK  id','user_id','schedule_id','main_image','inset_image','photo_path','caption','mood','taken_at','created_at','visibility']),'Postingan harian, foto, caption, dan arsip');
entity($p,2600,300,550,'moment_tags',array_map(fn($x)=>[$x,in_array($x,['PK  id','moment_id'],true)?(str_contains($x,'PK')?'PK':'FK'):''],['PK  id','moment_id','tag_label']),'Label / hashtag untuk momen');
entity($p,2600,650,550,'post_comments',array_map(fn($x)=>[$x,in_array($x,['PK  id','post_id','user_id'],true)?($x==='PK  id'?'PK':'FK*'):''],['PK  id','post_id','user_id','comment','created_at']),'post_id → moments.id · user_id → users.id');
entity($p,2600,1030,550,'post_reactions',array_map(fn($x)=>[$x,in_array($x,['PK  id','post_id','user_id'],true)?($x==='PK  id'?'PK':'FK*'):''],['PK  id','post_id','user_id','type','reaction','created_at']),'post_id → moments.id · user_id → users.id');
entity($p,2600,1430,550,'post_shares',array_map(fn($x)=>[$x,in_array($x,['PK  id','post_id','user_id'],true)?($x==='PK  id'?'PK':'FK*'):''],['PK  id','post_id','user_id','created_at']),'post_id → moments.id · user_id → users.id');
$p[]='<rect x="80" y="2180" width="3440" height="230" rx="18" fill="#FFFFFF" stroke="#DDD5EF" stroke-width="2"/>';$p[]=t(110,2225,'CARA MEMBACA',20,'#7558D1',750);$p[]=t(110,2270,'PK = primary key  ·  FK = foreign key  ·  FK* = relasi logis dari pemakaian aplikasi / kolom *_id (belum dipastikan constraint database)',19,'#241B35',500);$p[]=t(110,2315,'Kalender dan rekap bulanan dihitung dari moments.created_at + schedules.start_time/status; notifikasi jadwal dan feed bukan tabel tersendiri.',19,'#241B35',500);$p[]=t(110,2360,'academic_schedule adalah tabel lama yang terpisah dari schedules yang dipakai Kalender/Todo. Migrations adalah metadata internal CodeIgniter, bukan data fitur.',19,'#746B83',450);
saveSvg($out,'dailee-erd.svg',$p);

$f=svgStart(2600,2100,'Dailee — Alur Fitur','Alur data utama dari pendaftaran sampai home feed, unggahan momen, interaksi, hubungan sosial, pesan langsung, kalender, arsip, profil, dan rekap bulanan.'); heading($f,'DAILEE · ALUR DATA FITUR','Dari aktivitas pengguna ke tabel yang menyimpan data • fitur turunan ditandai sebagai hasil query, bukan tabel');
function flowbox(&$f,$x,$y,$w,$h,$title,$lines,$accent='#7558D1'): void {$f[]='<g filter="url(#shadow)"><rect x="'.$x.'" y="'.$y.'" width="'.$w.'" height="'.$h.'" rx="20" fill="#FFFFFF" stroke="'.$accent.'" stroke-width="3"/></g>'.t($x+22,$y+38,$title,23,$accent,750);foreach($lines as $i=>$line)$f[]=t($x+22,$y+76+$i*28,$line,18,'#241B35',500);}
function flowarrow(&$f,$x1,$y1,$x2,$y2,$label=null,$dashed=false): void {$c=$dashed?'#F29A38':'#8B7BB2';$mk=$dashed?'arrowDashed':'arrow';$d=$dashed?' stroke-dasharray="10 8"':'';$f[]='<path d="M'.$x1.' '.$y1.' L'.$x2.' '.$y2.'" fill="none" stroke="'.$c.'" stroke-width="3"'.$d.' marker-end="url(#'.$mk.')"/>'.($label?t(($x1+$x2)/2,($y1+$y2)/2-10,$label,15,$c,650,'middle'):'');}
flowbox($f,90,170,480,170,'1 · AKUN & AUTENTIKASI',['Daftar / login → users','Profil, avatar, bio, lokasi, pendidikan']);flowbox($f,760,170,480,170,'2 · HOME FEED',['Momen sendiri + teman','Friends of Friends melalui relasi accepted']);flowbox($f,1430,170,480,170,'3 · TANGKAP MOMEN',['Ambil selfie + foto utama','Caption, mood, privasi, waktu']);flowbox($f,2090,170,420,170,'SIMPAN',['users.id → moments.user_id','opsional moments.schedule_id']);flowarrow($f,570,255,760,255);flowarrow($f,1240,255,1430,255);flowarrow($f,1910,255,2090,255);
flowbox($f,90,570,480,210,'4 · HUBUNGAN SOSIAL',['Permintaan → friendships.pending','Terima → accepted (mutual dua arah)','Follow/unfollow → follows independen']);flowbox($f,760,570,480,210,'5 · AKSI PADA MOMEN',['Like / emoji → post_reactions','Komentar → post_comments','Share → post_shares']);flowbox($f,1430,570,480,210,'6 · INBOX / DM',['Pilih teman mutual','Pesan masuk/keluar tersimpan di chats','sender_id dan receiver_id']);flowbox($f,2090,570,420,210,'AKSES FEED',['friendships.status = accepted','visibility menentukan audiens','Follow tidak otomatis menjadi teman']);flowarrow($f,570,675,760,675);flowarrow($f,1240,675,1430,675);flowarrow($f,1910,675,2090,675);
flowbox($f,90,1050,480,220,'7 · AGENDA & TUGAS',['Buat agenda / to-do → schedules','Tanggal, jam, status, lokasi','Pengingat & sinkron kalender']);flowbox($f,760,1050,480,220,'8 · MEMORIES / KALENDER',['Arsip harian: moments.created_at','Agenda harian: schedules.start_time','Foto agenda dapat ditautkan ke momen']);flowbox($f,1430,1050,480,220,'9 · REKAP BULANAN',['Pilih bulan → kumpulkan data bulan itu','Jumlah momen / hari aktif','Agenda selesai & total agenda']);flowbox($f,2090,1050,420,220,'10 · PROFIL',['users + statistik relasi','Teman, followers, following','Log milik akun']);flowarrow($f,570,1160,760,1160);flowarrow($f,1240,1160,1430,1160);flowarrow($f,1910,1160,2090,1160);
flowbox($f,90,1530,480,230,'TABEL PENYIMPANAN',['users · friendships · follows','moments · schedules · chats','post_comments / reactions / shares','moment_tags']);flowbox($f,760,1530,480,230,'DATA TURUNAN',['Feed = query + izin visibilitas','Notifikasi = jadwal terdekat','Rekap = agregasi per bulan','Bukan tabel terpisah']);flowbox($f,1430,1530,480,230,'ARSIP TERINTEGRASI',['Foto dan agenda ditampilkan per tanggal','schedule_id menautkan agenda ke momen','Momen tanpa agenda tetap dapat diarsipkan']);flowbox($f,2090,1530,420,230,'CATATAN SKEMA',['FK* di ERD = relasi aplikasi','academic_schedule = tabel legacy','Bahasa / tema UI bukan tabel database']);flowarrow($f,330,1270,330,1530,'tulis / baca');flowarrow($f,1000,1270,1000,1530,'query');flowarrow($f,1670,1270,1670,1530,'agregasi');flowarrow($f,2300,1270,2300,1530,'ambil profil');
$f[]=t(90,1890,'ALUR INTI',19,'#7558D1',750);$f[]=t(90,1930,'Akun → Feed → Momen → Interaksi sosial → Memories & Kalender → Arsip harian → Rekap bulanan',22,'#241B35',600);$f[]=t(90,1980,'Diagram mengikuti schema dan controller aplikasi saat ini; notifikasi, feed, dan rekap dibentuk dari query.',17,'#746B83',450);saveSvg($out,'dailee-feature-flow.svg',$f);
